window.STUDY_DATA['en'] = {"id":"en","name":"General English","shortName":"General EN","lang":"en-GB","langLabel":"EN","subtitle":"Winning Strategy Units 1–3 · AV · Grammar File","accentColor":"#2563EB","defaultUnits":["u3"],"units":[{"id":"u1","group":"Winning Strategy","label":"Unit 1","title":"Unit 1 · Passport to the Future (Infinitive, Complex Subject)"},{"id":"u2","group":"Winning Strategy","label":"Unit 2","title":"Unit 2 · Necessary Evil? (Participles)"},{"id":"u3","group":"Winning Strategy","label":"Unit 3","title":"Unit 3 · From Surviving to Thriving (Gerund)"}],"cards":[{"id":"en-u1-001","unit":"u1","term":"tailored (adj)","ru":"сшитый на заказ; специально разработанный/подобранный (под кого-л./что-л.)","def":"made or changed especially to be suitable for a particular person, situation or purpose","coll":"a tailored suit/ programme/ benefit","ex":"The project clearly requires a tailored computer system.","tag":"Unit 1 AV"},{"id":"en-u1-002","unit":"u1","term":"to adapt (v)","ru":"приспосабливаться, адаптироваться; приспосабливать, адаптировать; переделывать (роман — для экрана)","def":"to change, or to change something, to suit different conditions, situations, or uses","coll":"to adapt to a new environment/ climate change; to adapt a novel for television/screen; to adapt plans to the circumstances; to be adapted to suit individual needs/tastes","ex":"His best asset is his ability to adapt quickly. / The best-selling computer game has been adapted for a younger audience. / To remain competitive the company has to be able to adapt to the changing marketplace.","tag":"Unit 1 AV"},{"id":"en-u1-003","unit":"u1","term":"to foster (v)","ru":"способствовать развитию, развивать, поощрять, укреплять","def":"to encourage the development or growth of something","coll":"to foster innovation/ creativity/ cooperation/ understanding/ relations","ex":"She believes in fostering innovation through competition. / The idea is to foster cooperation between small businesses in the local area.","tag":"Unit 1 AV"},{"id":"en-u1-004","unit":"u1","term":"to engage (v)","ru":"1) привлекать, захватывать (внимание, интерес), вовлекать; 2) включаться, участвовать, взаимодействовать","def":"1. to interest sb in sth and keep them thinking about it; 2. to become involved, or have contact, with sb or sth","coll":"to engage sb's attention/interest; to engage students/ the audience; to engage emotionally","ex":"(1) We're always looking out for new subjects that will engage our readers. (2) She's an intelligent child but in class she doesn't really engage.","tag":"Unit 1 AV"},{"id":"en-u1-005","unit":"u1","term":"engagement (n)","ru":"вовлечённость, участие, (активное) взаимодействие","def":"being involved with sb/sth in an attempt to understand them/it","coll":"engagement with sb/sth; engagement in politics/ community activities; to increase student engagement","ex":"He was known for his engagement with the problems of the most difficult students. / Her engagement in class discussions really picked up as the topic deepened.","tag":"Unit 1 AV"},{"id":"en-u1-006","unit":"u1","term":"customized (adj)","ru":"сделанный на заказ, по индивидуальным требованиям (покупателя/пользователя)","def":"made or changed according to the buyer's or user's needs","coll":"customized solutions/ training/ programme/ curriculum","ex":"Creating a customized album can be a long process.","tag":"Unit 1 AV"},{"id":"en-u1-007","unit":"u1","term":"to refer to (phr v)","ru":"относиться к; обозначать, означать (о термине); упоминать, ссылаться на","def":"to describe or to be connected to sb/sth","coll":"to refer to sb/sth","ex":"The term \"Arts\" usually refers to humanities and social sciences.","tag":"Unit 1 AV"},{"id":"en-u1-008","unit":"u1","term":"to impact (v)","ru":"влиять, оказывать воздействие","def":"to have an influence on sth","coll":"to impact (on) sth","ex":"People want to hear about those issues that impact their lives.","tag":"Unit 1 AV"},{"id":"en-u1-009","unit":"u1","term":"impact (n)","ru":"(сильное) влияние, воздействие","def":"the powerful effect that sb/sth has on sb/sth","coll":"to have a positive/ negative/ huge/ significant impact on sth/sb","ex":"The anti-smoking campaign had quite an impact on young people.","tag":"Unit 1 AV"},{"id":"en-u1-010","unit":"u1","term":"curriculum (n) (pl curricula)","ru":"учебная программа, учебный план","def":"the subjects studied in a school, college, etc. and what each subject includes","coll":"the school/ national curriculum; to be on the curriculum","ex":"Latin is not on the curriculum.","tag":"Unit 1 AV"},{"id":"en-u1-011","unit":"u1","term":"personalised (adj)","ru":"именной; персонализированный, индивидуальный","def":"used to describe an object that has someone's name on it, or that has been made for a particular person","coll":"a personalised learning plan","ex":"His car has a personalized number plate - TJ 1.","tag":"Unit 1 AV"},{"id":"en-u1-012","unit":"u1","term":"outcome (n)","ru":"результат, исход, итог","def":"a result or effect of an action, situation, or event","coll":"to predict the outcome of sth; a positive/ desired/ possible/ successful outcome; to impact the outcome","ex":"","tag":"Unit 1 AV"},{"id":"en-u1-013","unit":"u1","term":"to address (v)","ru":"заниматься (проблемой), решать, рассматривать; удовлетворять (потребности)","def":"to give attention to or deal with a matter or problem","coll":"to address an issue/ concern/ problem/ question; to address the needs of students","ex":"The government has to address the rise in violent crime.","tag":"Unit 1 AV"},{"id":"en-u1-014","unit":"u1","term":"to enhance (v)","ru":"повышать, улучшать, усиливать","def":"to improve the quality, amount, or strength of sth","coll":"to enhance the quality of life / sb's reputation/ career prospects/ image/ productivity/ performance","ex":"The project was designed to enhance the experience of museum visitors.","tag":"Unit 1 AV"},{"id":"en-u1-015","unit":"u1","term":"to identify (v)","ru":"выявлять, определять, устанавливать","def":"to find or discover sb/sth","coll":"to identify a need/factor/cause/source","ex":"First of all, we must identify the problem areas.","tag":"Unit 1 AV"},{"id":"en-u1-016","unit":"u1","term":"to thrive (v)","ru":"процветать, преуспевать, успешно развиваться","def":"to grow, develop, or be successful","coll":"to thrive academically/ professionally","ex":"New businesses thrive in this area.","tag":"Unit 1 AV"},{"id":"en-u1-017","unit":"u1","term":"to pose (v)","ru":"представлять (угрозу), создавать (проблему, риск), ставить (задачу)","def":"to cause sth, especially a problem or difficulty","coll":"to pose a threat/ problem/ risk/ challenge to sth/sb/ for sb","ex":"The outcome of the vote poses a serious challenge to the government's credibility.","tag":"Unit 1 AV"},{"id":"en-u1-018","unit":"u1","term":"to navigate (v)","ru":"успешно справляться (с трудной ситуацией), преодолевать","def":"to successfully find your way through a difficult situation","coll":"to navigate a crisis/ problem/ challenge","ex":"The IT department worked all night to help the company navigate a major cybersecurity problem before any data was leaked.","tag":"Unit 1 AV"},{"id":"en-u1-019","unit":"u1","term":"to hinder (v)","ru":"мешать, препятствовать, тормозить","def":"to limit the ability of someone to do something, or to limit the development of something","coll":"to hinder progress/ development/ growth/ efforts/ ability/ access; to hinder sb/sth from sth/doing sth","ex":"Which factors hinder a child's progress at school? / The injury hindered him from playing his best.","tag":"Unit 1 AV"},{"id":"en-u1-020","unit":"u1","term":"to interpret (v)","ru":"толковать, трактовать, интерпретировать; расценивать (как)","def":"to decide what the intended meaning of something is","coll":"to interpret data/ results/ signs/ law; to interpret sth as sth","ex":"The data can be interpreted in many different ways.","tag":"Unit 1 AV"},{"id":"en-u1-021","unit":"u1","term":"to misinterpret (v)","ru":"неверно истолковать, неправильно понять","def":"to incorrectly interpret","coll":"to misinterpret sb's words/ silence/ gestures","ex":"Don't misinterpret my silence as a lack of interest.","tag":"Unit 1 AV"},{"id":"en-u1-022","unit":"u1","term":"interpretation (n)","ru":"толкование, трактовка, интерпретация","def":"the particular way in which something is understood or explained","coll":"to be open to interpretation; a modern/narrow interpretation of sth","ex":"Are the test results open to interpretation?","tag":"Unit 1 AV"},{"id":"en-u1-023","unit":"u1","term":"sensitive (adj)","ru":"деликатный, щекотливый; (об информации) конфиденциальный","def":"that you have to treat with great care because it may offend people or make them angry or embarrassed","coll":"a sensitive issue/ topic/ matter/ area/ subject/ question; sensitive information/data","ex":"It is crucial to verify every fact before publishing a story about such a politically sensitive matter.","tag":"Unit 1 AV"},{"id":"en-u1-024","unit":"u1","term":"to assess (v)","ru":"оценивать","def":"to judge or decide the amount, value, quality, or importance of something","coll":"to assess risks/ damage/ performance/ needs/ the impact of/ a situation; to assess accurately/ properly/ formally/ critically","ex":"You should regularly assess your own performance to identify areas for improvement.","tag":"Unit 1 AV"},{"id":"en-u1-025","unit":"u1","term":"assessment (n)","ru":"оценка, оценивание","def":"the act of judging or deciding the amount, value, quality, or importance of something, or the judgment or decision that is made","coll":"","ex":"The assessment of the environmental impact showed that the new factory would harm local wildlife.","tag":"Unit 1 AV"},{"id":"en-u1-026","unit":"u1","term":"to highlight (v)","ru":"подчёркивать, акцентировать, привлекать внимание к, выделять","def":"to attract attention to or emphasize sth important, or to make sth easier to notice","coll":"to highlight an issue/ a problem/ fact/ need/ concern; to highlight the importance of sth","ex":"The accident highlights the need for new safety measures.","tag":"Unit 1 AV"},{"id":"en-u1-027","unit":"u1","term":"to erode (v)","ru":"постепенно подрывать, разрушать; размывать","def":"to slowly reduce or destroy sth","coll":"to erode confidence/ trust/ power/ land","ex":"Lying to your team will quickly erode their trust in your leadership.","tag":"Unit 1 AV"},{"id":"en-u1-028","unit":"u1","term":"erosion (n)","ru":"эрозия; постепенное разрушение, подрыв, утрата","def":"the gradual reduction or destruction of sth","coll":"soil/coastal erosion; erosion of trust/ moral standards","ex":"The report warned that without immediate action, coastal erosion would swallow several seaside homes within a decade.","tag":"Unit 1 AV"},{"id":"en-u1-029","unit":"u1","term":"to contribute (v)","ru":"1) жертвовать, вносить (деньги, помощь), делать вклад; 2) способствовать, содействовать, быть одной из причин","def":"1. to give sth, especially money or goods, to help achieve or provide sth; 2. to be one of the causes of sth","coll":"to contribute money/help/clothes to sth; to contribute greatly/ financially; to contribute actively/directly/effectively; to contribute to/towards sth","ex":"(1) Over £75 million was contributed to the campaign. (2) It is well known that UV radiation contributes to the development of skin cancer.","tag":"Unit 1 AV"},{"id":"en-u1-030","unit":"u1","term":"contribution (n)","ru":"вклад, содействие","def":"an action or a service that helps to cause or increase sth, usually (but not necessarily) sth good or valuable","coll":"to make a positive/valuable/crucial/small contribution to sth","ex":"He made a very positive contribution to the success of the project.","tag":"Unit 1 AV"},{"id":"en-u1-031","unit":"u1","term":"contributor (n)","ru":"тот, кто вносит вклад; жертвователь, спонсор; (фактор) способствующий чему-л.","def":"a person or thing that provides money or goods to help pay for or support sth","coll":"a regular/frequent/ an important/ the largest/ major contributor","ex":"Older people are important contributors to the economy.","tag":"Unit 1 AV"},{"id":"en-u1-032","unit":"u1","term":"contributing (adj)","ru":"способствующий, сопутствующий","def":"used to describe sth that helps to make sth happen","coll":"a contributing factor","ex":"Stress was a contributing factor in his heart attack.","tag":"Unit 1 AV"},{"id":"en-u1-033","unit":"u1","term":"adoption (n)","ru":"принятие, внедрение","def":"the decision to start using sth such as an idea, a plan or a name","coll":"to promote/ hinder/ resist the adoption of renewable sources of energy/ electric cars/ AI","ex":"The widespread adoption of new information technology could save $162 billion a year.","tag":"Unit 1 AV"},{"id":"en-u1-034","unit":"u1","term":"to promote (v)","ru":"содействовать, способствовать; продвигать, популяризировать","def":"to encourage people to like, buy, use, do, or support sth","coll":"to promote peace/ health/ awareness/ understanding/ sales/ equality","ex":"Libraries play a crucial role in promoting reading habits among young children.","tag":"Unit 1 AV"},{"id":"en-u1-035","unit":"u1","term":"promotion (n)","ru":"продвижение, содействие, популяризация; реклама","def":"activities intended to make people aware of a product, service, or cause and encourage them to buy or support it","coll":"promotion of trade/ tourism/ economic growth/ literacy/ culture/ cooperation","ex":"He dedicated his life to the promotion of equal opportunities in the workplace.","tag":"Unit 1 AV"},{"id":"en-u1-036","unit":"u1","term":"literacy (n) (ant. illiteracy)","ru":"1) грамотность; 2) грамотность/осведомлённость в какой-л. области. illiteracy\\* — неграмотность","def":"1. the ability to read and write; 2. knowledge of a particular subject, or a particular type of knowledge","coll":"literacy levels/rates/skills; computer/ health/ financial/ economic literacy","ex":"(1) The government launched a new campaign to improve adult literacy rates across rural provinces. (2) Low health literacy often prevents patients from following medical advice correctly.","tag":"Unit 1 AV"},{"id":"en-u1-037","unit":"u1","term":"literate (adj) (ant. illiterate)","ru":"1) грамотный; 2) разбирающийся, сведущий (в области). illiterate\\* — неграмотный","def":"1. able to read and write; 2. having knowledge or skill in a particular area","coll":"literate population; financially/ digitally/ media- /computer -literate","ex":"(1) The charity's main goal is to ensure every child in the region becomes literate by the age of ten. (2) In an era of fake news, children must become media-literate to distinguish between reliable sources and propaganda.","tag":"Unit 1 AV"},{"id":"en-u1-038","unit":"u1","term":"to prioritize (v)","ru":"расставлять приоритеты; уделять первостепенное внимание, ставить на первое место","def":"to arrange in order of importance so that you can deal with the most important things before the others","coll":"to prioritize tasks/needs/safety/health; to prioritize sth over sth; to learn to prioritize","ex":"She always tries to prioritize quality time with her children despite her busy workload. / Many office workers prioritize their careers over their personal well-being, which leads to chronic stress and burnout.","tag":"Unit 1 AV"},{"id":"en-u1-039","unit":"u1","term":"mindset (n)","ru":"образ мышления, склад ума, установка","def":"a person's way of thinking or their established attitudes","coll":"a growth/fixed/positive mindset; to change one's/sb's mindset","ex":"To succeed in sales, you need a competitive mindset.","tag":"Unit 1 AV"},{"id":"en-u1-040","unit":"u1","term":"to be set in stone (expr)","ru":"быть незыблемым, неизменным, окончательным","def":"to be fixed and unchangeable; permanent","coll":"","ex":"The deadline isn't set in stone, so we can discuss it.","tag":"Unit 1 AV"},{"id":"en-u1-041","unit":"u1","term":"capacity (n)","ru":"способность, возможности, потенциал","def":"sb's ability to understand or to do sth","coll":"capacity to do sth; capacity for growth/ development/ hard work; beyond sb's capacity; within sb's capacity; mental/intellectual/earning capacity; to have/ increase/ reduce/ restrict/ lose the capacity to do sth; a great/enormous capacity","ex":"A habit becomes an addiction when it reduces your capacity to enjoy life. / Do you think it's within his capacity to do the job without making a mess of it?","tag":"Unit 1 AV"},{"id":"en-u1-042","unit":"u1","term":"to evolve (v)","ru":"(постепенно) развиваться, эволюционировать; превращаться (в)","def":"to develop gradually from a simple to a more complex form","coll":"to evolve (from sth) (into sth)","ex":"The idea evolved from a drawing I discovered in the attic. / The company has evolved into a major chemical manufacturer.","tag":"Unit 1 AV"},{"id":"en-u1-043","unit":"u1","term":"to take on (phr v)","ru":"брать на себя (ответственность, задачу, роль), браться за; принимать (вызов)","def":"to accept a responsibility or challenge","coll":"to take on risk/ a challenge/ project/ role/ task","ex":"I can't take on any more tasks today.","tag":"Unit 1 AV"},{"id":"en-u1-044","unit":"u1","term":"to emerge (v)","ru":"появляться, возникать; выясняться, становиться известным; выдвинуться (в качестве кого-л.)","def":"to appear, to become known","coll":"to emerge as sth; it emerges that …; challenges/opportunities emerge","ex":"He emerged as a key figure in the campaign. / It emerged that the company was going to be sold.","tag":"Unit 1 AV"},{"id":"en-u1-045","unit":"u1","term":"to collaborate (v)","ru":"сотрудничать, работать совместно","def":"to work together with sb in order to produce or achieve sth","coll":"to collaborate with sb on sth","ex":"We should collaborate with the design team on this project.","tag":"Unit 1 AV"},{"id":"en-u1-046","unit":"u1","term":"collaboration (n)","ru":"сотрудничество, совместная работа, взаимодействие","def":"the act of working with another person or group of people to create or produce sth","coll":"close/effective collaboration; to foster/hinder collaboration; in collaboration with sb (on sth)","ex":"The government worked in close collaboration with teachers on the new curriculum.","tag":"Unit 1 AV"},{"id":"en-u1-047","unit":"u1","term":"detrimental (adj)","ru":"пагубный, вредный","def":"causing harm, damaging","coll":"a detrimental effect/impact; to be detrimental to health/ environment /economy","ex":"The policy is detrimental to the peace process.","tag":"Unit 1 AV"},{"id":"en-u1-048","unit":"u1","term":"expertise (n)","ru":"профессиональные знания и опыт, компетентность","def":"expert skill or knowledge in a particular field","coll":"professional/scientific/technical expertise; to have/ possess/ lack/ gain/ develop/share expertise in sth/ doing sth; considerable/ great expertise","ex":"They have considerable expertise in dealing with these matters.","tag":"Unit 1 AV"},{"id":"en-u1-049","unit":"u1","term":"to struggle (v)","ru":"с трудом пытаться, изо всех сил стараться; бороться (за); испытывать трудности (с)","def":"to try very hard to do sth when it is difficult or when there are a lot of problems","coll":"to struggle to do sth; to struggle for breath/survival; to struggle hard/desperately/financially; to struggle with sth","ex":"Local workers were struggling to find employment. / During the crisis companies struggled for survival. / The students are struggling with the essay.","tag":"Unit 1 AV"},{"id":"en-u1-050","unit":"u1","term":"committed (adj)","ru":"преданный (делу), приверженный","def":"willing to work hard and give your time and energy to sth; believing strongly in sth","coll":"committed to (doing) sth; a fully/deeply committed team member","ex":"We are committed to the ideal of equality.","tag":"Unit 1 AV"},{"id":"en-u1-051","unit":"u1","term":"commitment (n)","ru":"приверженность, преданность (делу), обязательство","def":"the desire to work hard and give your energy and time to a job or an activity","coll":"to show /demonstrate/ lack commitment; strong/long-term commitment to sth","ex":"The politician is known for his commitment to equality and social justice.","tag":"Unit 1 AV"},{"id":"en-u1-052","unit":"u1","term":"to assign (v)","ru":"поручать, назначать, распределять, выделять (время)","def":"to give sb sth that they can use, or some work or responsibility","coll":"to assign a task/ roles/ responsibility to sb; to assign time/a date/a day for sth; to assign a mentor; to assign sb to do sth","ex":"I'll assign this report to the junior analyst. / Have you assigned a date for the interview yet? / The committee has been assigned to review all safety protocols.","tag":"Unit 1 AV"},{"id":"en-u2-001","unit":"u2","term":"to boost (v)","ru":"повышать, усиливать, стимулировать","def":"to increase, or improve sth","coll":"to boost sales/exports/profits; to boost economy/an industry; to boost morale/confidence/self-esteem","ex":"The movie helped boost her screen career.","tag":"Unit 2 AV"},{"id":"en-u2-002","unit":"u2","term":"to embark on (phr v)","ru":"приступать к, начинать что-то новое","def":"to start sth new and important","coll":"to embark on a career/a project/a plan/a programme/an adventure/studies","ex":"She is ready to embark on her adventure.","tag":"Unit 2 AV"},{"id":"en-u2-003","unit":"u2","term":"tantalizing (adj)","ru":"заманчивый, дразнящий","def":"causing excitement, interest, desire","coll":"a tantalizing question/job offer/taste of success","ex":"She caught a tantalizing glimpse of the blue ocean through the trees.","tag":"Unit 2 AV"},{"id":"en-u2-004","unit":"u2","term":"to delve into (phr v)","ru":"углубляться, вникать в","def":"to try hard to find out more information about sth, to explore","coll":"to delve into history/the past/sb's private life","ex":"She said she was tired of journalists delving into her private life.","tag":"Unit 2 AV"},{"id":"en-u2-005","unit":"u2","term":"intriguing (adj)","ru":"интригующий, увлекательный","def":"very interesting because of being unusual or not having an obvious answer","coll":"an intriguing question/possibility/story/personality","ex":"This intriguing book is both thoughtful and informative.","tag":"Unit 2 AV"},{"id":"en-u2-006","unit":"u2","term":"to absorb (v)","ru":"усваивать, впитывать","def":"to learn or understand facts and ideas and remember them","coll":"to absorb information/news","ex":"It's hard to absorb so much information.","tag":"Unit 2 AV"},{"id":"en-u2-007","unit":"u2","term":"to compel (v)","ru":"вынуждать, заставлять","def":"to force somebody to do something","coll":"to compel sb to do sth; to feel compelled to do sth","ex":"Drivers are compelled by law to have insurance. / I feel compelled to write and tell you how much I enjoyed your book.","tag":"Unit 2 AV"},{"id":"en-u2-008","unit":"u2","term":"to immerse (v)","ru":"погружать(ся)","def":"to become or make sb completely involved in something","coll":"to immerse oneself in sth; to be immersed in sth","ex":"I immediately immersed myself in the task. / They were immersed in conversation in the corner.","tag":"Unit 2 AV"},{"id":"en-u2-009","unit":"u2","term":"immersion (n)","ru":"погружение","def":"complete involvement in sth","coll":"an immersion method/course","ex":"The course offers the opportunity for total immersion in the language and culture.","tag":"Unit 2 AV"},{"id":"en-u2-010","unit":"u2","term":"multitasking (n)","ru":"многозадачность","def":"the ability to do several things at the same time","coll":"multitasking skills","ex":"To succeed, you will need strong multitasking skills.","tag":"Unit 2 AV"},{"id":"en-u2-011","unit":"u2","term":"decision making (n phr)","ru":"принятие решений","def":"the process of making a choice about sth after thinking about and/or discussing several possibilities","coll":"decision-making processes/skills","ex":"We need to take a lot of factors into account in our decision making.","tag":"Unit 2 AV"},{"id":"en-u2-012","unit":"u2","term":"problem-solving (n)","ru":"решение проблем","def":"the process of finding solutions to some problem","coll":"problem-solving abilities/skills/strategies","ex":"The programme offers training in basic problem-solving strategies.","tag":"Unit 2 AV"},{"id":"en-u2-013","unit":"u2","term":"to enrich (v)","ru":"обогащать","def":"to improve the quality of something, often by adding something to it","coll":"","ex":"The study of science has enriched all our lives.","tag":"Unit 2 AV"},{"id":"en-u2-014","unit":"u2","term":"enrichment (n)","ru":"обогащение","def":"the act of improving the quality of sth, often by adding sth to it","coll":"cultural/spiritual enrichment","ex":"Education provides enrichment to the lives of individuals in a number of ways.","tag":"Unit 2 AV"},{"id":"en-u2-015","unit":"u2","term":"enlightened (adj)","ru":"просвещённый, прогрессивный, здравый","def":"showing understanding, acting in a positive way, and not following old-fashioned or false beliefs","coll":"an enlightened mind/opinion/attitude/idea/approach/policy","ex":"The school has an enlightened policy of teaching boys to cook.","tag":"Unit 2 AV"},{"id":"en-u2-016","unit":"u2","term":"to head towards (phr v)","ru":"направляться к; двигаться к (результату)","def":"1) to move in a particular direction; 2) to advance, make progress to a future outcome or goal","coll":"","ex":"1) We'll head towards the beach for a picnic. 2) The project is heading towards completion.","tag":"Unit 2 AV"},{"id":"en-u2-017","unit":"u2","term":"to prevail (v)","ru":"преобладать, господствовать","def":"to exist or be very common at a particular time or in a particular place","coll":"to prevail among sb","ex":"These beliefs still prevail among certain social groups.","tag":"Unit 2 AV"},{"id":"en-u2-018","unit":"u2","term":"prevailing (adj)","ru":"преобладающий, господствующий","def":"existing or most common at a particular time","coll":"a prevailing trend/opinion/attitude/view","ex":"The prevailing view seems to be that they will find her guilty.","tag":"Unit 2 AV"},{"id":"en-u2-019","unit":"u2","term":"to retreat (v)","ru":"отступать, удаляться","def":"to move away or back","coll":"","ex":"He watched her retreating figure.","tag":"Unit 2 AV"},{"id":"en-u2-020","unit":"u2","term":"retreat (n)","ru":"1) уход, бегство (от чего-то); 2) убежище, уединённое место","def":"1) an act of trying to escape from a particular situation to one that you think is safer or more pleasant; 2) a quiet private place you go to in order to get away from your usual life","coll":"1) a retreat from/into sth; 2) a country/weekend/summer/secret retreat","ex":"1) Is watching series a retreat from reality? 2) They're staying here at their secret retreat from life in the city.","tag":"Unit 2 AV"},{"id":"en-u2-021","unit":"u2","term":"secluded (adj)","ru":"уединённый, укромный","def":"quiet and private","coll":"a secluded corner/spot/garden; to lead a secluded life","ex":"We managed to find a secluded spot for our picnic.","tag":"Unit 2 AV"},{"id":"en-u2-022","unit":"u2","term":"to intrude (v)","ru":"вторгаться, мешать","def":"to go into a place or situation in which you are not wanted or expected to","coll":"to intrude into/on/upon sb's personal life","ex":"I hope I am not intruding.","tag":"Unit 2 AV"},{"id":"en-u2-023","unit":"u2","term":"intrusion (n)","ru":"вторжение, вмешательство","def":"sth that affects a situation or people's lives in a way that they do not want","coll":"intrusion on/upon sth; intrusion into sth; media/press intrusion","ex":"This was another example of press intrusion into the affairs of the royals.","tag":"Unit 2 AV"},{"id":"en-u2-024","unit":"u2","term":"compelling (adj)","ru":"захватывающий, притягательный, убедительный","def":"making you pay attention to it because it is so interesting and exciting","coll":"a compelling film/story; compelling eyes/appearance","ex":"Her latest book makes compelling reading.","tag":"Unit 2 AV"},{"id":"en-u2-025","unit":"u2","term":"overwhelm (n)","ru":"ощущение перегруженности, подавленности","def":"the fact or feeling of not being able to cope or deal with sth","coll":"a sense of constant overwhelm","ex":"Many people today live with a sense of constant overwhelm, struggling to keep up with work, news, and social pressures.","tag":"Unit 2 AV"},{"id":"en-u2-026","unit":"u2","term":"to overwhelm (v)","ru":"1) переполнять, охватывать (о чувствах); 2) заваливать, подавлять","def":"1) to have such a strong emotional effect on sb that it is difficult for them to resist or know how to react; 2) to be so bad or so great that a person cannot deal with it; to give too much of a thing to a person","coll":"1) to be/feel overwhelmed by; 2) to be overwhelmed by orders/requests","ex":"1) She was overwhelmed by feelings of guilt. 2) We were overwhelmed by requests for information.","tag":"Unit 2 AV"},{"id":"en-u2-027","unit":"u2","term":"overwhelming (adj)","ru":"огромный, всепоглощающий, непреодолимый, подавляющий","def":"very great or very strong; so powerful that you cannot resist it or decide how to react","coll":"overwhelming happiness/support/majority; an overwhelming desire/loss","ex":"There was overwhelming support for our policies.","tag":"Unit 2 AV"},{"id":"en-u2-028","unit":"u2","term":"to relieve (v)","ru":"облегчать, снимать (боль, стресс)","def":"to remove or reduce an unpleasant feeling or pain","coll":"to relieve anxiety/guilt/stress; to feel relieved to do sth","ex":"Being able to tell the truth at last seemed to relieve her.","tag":"Unit 2 AV"},{"id":"en-u2-029","unit":"u2","term":"relief (n)","ru":"облегчение; помощь","def":"the act of removing or reducing pain, worry, etc.","coll":"relief of symptoms/suffering/poverty/pain; to provide relief aid; to provide/bring relief from sth","ex":"The drugs only provided temporary relief from the pain.","tag":"Unit 2 AV"},{"id":"en-u2-030","unit":"u2","term":"distressing (adj)","ru":"удручающий, тревожный, мучительный","def":"making you feel extremely upset, especially because somebody is suffering","coll":"a distressing news report/documentary","ex":"The divorce was extremely distressing for the children.","tag":"Unit 2 AV"},{"id":"en-u2-031","unit":"u2","term":"to distort (v)","ru":"искажать","def":"to change facts, ideas, etc. so that they are no longer correct or true","coll":"to distort facts/the truth/a message","ex":"Newspapers are often guilty of distorting the truth.","tag":"Unit 2 AV"},{"id":"en-u2-032","unit":"u2","term":"extravagant (adj)","ru":"1) расточительный; 2) непомерно дорогой, роскошный","def":"1) spending a lot more money or using a lot more of sth than you can afford or than is necessary; 2) costing a lot more money than you can afford or is necessary","coll":"1) to be extravagant with sth; 2) an extravagant gift/lifestyle","ex":"1) Residents were warned not to be extravagant with water, in view of the low rainfall this year. 2) He bought us all these extravagant presents he couldn't really afford.","tag":"Unit 2 AV"},{"id":"en-u2-033","unit":"u2","term":"core (adj)","ru":"основной, ключевой, центральный","def":"most important; main or essential","coll":"to be core to sth; core subjects/curriculum; a core issue/reason; core values/beliefs","ex":"The use of new technology is core to our strategy.","tag":"Unit 2 AV"},{"id":"en-u2-034","unit":"u2","term":"overstretched (adj)","ru":"перегруженный, работающий на пределе","def":"having more work or other activities than you can manage","coll":"overstretched staff/services/hospitals","ex":"Our staff work hard but the reality is they are overstretched.","tag":"Unit 2 AV"},{"id":"en-u2-035","unit":"u2","term":"to indulge (v)","ru":"позволять себе, баловать себя; предаваться","def":"to allow yourself to have or do sth that you like","coll":"to indulge in shopping/gossip; to indulge oneself with sth","ex":"I indulged myself with a long hot bath.","tag":"Unit 2 AV"},{"id":"en-u2-036","unit":"u2","term":"indulgent (adj)","ru":"снисходительный, потакающий; (о поступке) потакающий своим желаниям, баловство","def":"1) tending to allow sb to have or do whatever they want; 2) willing or too willing to ignore the weaknesses in sb/sth","coll":"indulgent parents; indulgent to/towards sb; to take an indulgent view of sth","ex":"She was indulgent towards her daughter.","tag":"Unit 2 AV"},{"id":"en-u2-037","unit":"u2","term":"indulgence (n)","ru":"потакание своим желаниям; слабость, удовольствие","def":"the state or act of having or doing whatever you want; the state of allowing sb to have or do whatever they want","coll":"to lead a life of indulgence; indulgence in sth","ex":"He has always dreamed of retiring early to lead a life of indulgence, filled with travel. / Chocolate is my only indulgence.","tag":"Unit 2 AV"},{"id":"en-u2-038","unit":"u2","term":"identity (n)","ru":"1) личность; 2) самобытность, идентичность","def":"1) who or what sb/sth is; 2) the qualities that make sth recognizable","coll":"1) to establish/reveal sb's identity; 2) national/cultural identity; a sense of identity; identity crisis","ex":"1) The killer's identity was kept secret. 2) Traveling abroad helped her understand her own cultural identity better. · 6a: Language plays a key role in shaping national identity.","tag":"Unit 2 AV"},{"id":"en-u2-039","unit":"u2","term":"to dilute (v)","ru":"разбавлять; ослаблять, размывать","def":"1) to make sth weaker by adding sth else; 2) to reduce its strength/quality","coll":"1) to dilute juice; to dilute with water; 2) to dilute the effect of sth/a message/a brand","ex":"1) The paint can be diluted with water to make a lighter shade. 2) Too much tourism can dilute the authenticity of local traditions. · 6a: The company diluted its brand by opening too many low-quality stores.","tag":"Unit 2 AV"},{"id":"en-u2-040","unit":"u2","term":"to consume (v)","ru":"1) потреблять, расходовать; 2) употреблять в пищу","def":"1) to use up (time, energy, resources); 2) to eat or drink","coll":"1) to consume energy/resources/time; 2) to consume alcohol","ex":"Large hotels consume enormous amounts of water every day. · 6a: Children consume a lot of sugar in soft drinks.","tag":"Unit 2 AV"},{"id":"en-u2-041","unit":"u2","term":"pristine (adj)","ru":"1) безупречный, как новый; 2) нетронутый, первозданный","def":"1) completely clean, new, or unspoiled; 2) in original perfect condition","coll":"in pristine condition; pristine beaches/forest/wilderness","ex":"The car is in pristine condition. / The coastline was pristine before mass tourism arrived. · 6a: The scientists explored a pristine part of the rainforest untouched by humans.","tag":"Unit 2 AV"},{"id":"en-u2-042","unit":"u2","term":"to swamp (v)","ru":"заваливать, наводнять","def":"to overwhelm sb/sth with too much of sth","coll":"to be swamped with requests/work; to be swamped with tourists","ex":"The small town is swamped with visitors every summer. · 6a: The small hospital was swamped with patients during the flu season.","tag":"Unit 2 AV"},{"id":"en-u2-043","unit":"u2","term":"to drain (v)","ru":"истощать, выкачивать","def":"to slowly remove or use up sth until little remains","coll":"to drain resources/energy/finances","ex":"Overtourism can drain a city's water supply. · 6a: The long meeting drained all my energy.","tag":"Unit 2 AV"},{"id":"en-u2-044","unit":"u2","term":"to account for (phr v)","ru":"1) объяснять; 2) составлять (долю)","def":"1) to explain the reason for sth, or to be the reason; 2) to make up a proportion of sth","coll":"1) to account for a delay/for one's actions; 2) to account for a percentage","ex":"1) He was unable to account for the error. 2) Tourism accounts for 15% of the country's GDP. · 6a: Women account for over half of the university's graduates this year.","tag":"Unit 2 AV"},{"id":"en-u2-045","unit":"u2","term":"emission (n)","ru":"выброс","def":"gas or substance released into the air, especially pollution","coll":"carbon/greenhouse gas emissions; to reduce emissions","ex":"Air travel emissions are a major concern for the environment. · 6a: The factory reduced its carbon emissions last year.","tag":"Unit 2 AV"},{"id":"en-u2-046","unit":"u2","term":"infamous (adj)","ru":"печально известный, пресловутый","def":"well known for something bad; having a bad reputation","coll":"to be/become infamous for; an infamous scandal","ex":"The city became infamous for its overcrowded streets. · 6a: The restaurant is infamous for bad service.","tag":"Unit 2 AV"},{"id":"en-u2-047","unit":"u2","term":"to impose (v)","ru":"вводить (налог, ограничение), навязывать","def":"to force a rule, tax, or belief onto sb/sth","coll":"to impose taxes/restrictions/rules","ex":"The government imposed a visitor limit on the historic site. · 6a: The teacher imposed strict rules on the class.","tag":"Unit 2 AV"},{"id":"en-u2-048","unit":"u2","term":"downside (n)","ru":"недостаток, минус); ant. upside (n) — (* плюс, преимущество","def":"a disadvantage or negative aspect of sth","coll":"the core downside; the downside is that...; to weigh the downsides of sth","ex":"The downside of tourism is rising rent for locals. · 6a: Every plan has a downside.","tag":"Unit 2 AV"},{"id":"en-u2-049","unit":"u2","term":"to evict (v)","ru":"выселять","def":"to legally force sb to leave a property","coll":"to evict a tenant; to evict from an apartment","ex":"Several families were evicted to make room for short-term rentals. · 6a: The landlord evicted the family for not paying rent.","tag":"Unit 2 AV"},{"id":"en-u2-050","unit":"u2","term":"to divert (v)","ru":"перенаправлять; отвлекать (внимание)","def":"to change the direction of something (traffic, money, attention)","coll":"to divert funds/traffic/a plane/attention","ex":"The city diverted public funds toward tourism infrastructure. · 6a: She diverted the conversation to a safer topic.","tag":"Unit 2 AV"},{"id":"en-u2-051","unit":"u2","term":"delicate (часть речи в AV guide не указана)","ru":"хрупкий; деликатный, щекотливый; нежный","def":"easily broken or damaged; requiring careful handling; sensitive","coll":"delicate plants/ecosystem; a delicate situation/topic; delicate skin","ex":"Coral reefs are extremely delicate ecosystems. · 6a: This is a delicate subject, so choose your words wisely.","tag":"Unit 2 AV"},{"id":"en-u2-052","unit":"u2","term":"to sustain (v)","ru":"1) поддерживать, сохранять; 2) обеспечивать (жизнь); 3) понести (ущерб, потери)","def":"1) to keep something going over time; 2) to support or maintain; 3) to suffer or experience","coll":"1) to sustain growth/relationships; 2) to sustain life/a family/population; 3) to sustain damage/losses/injuries","ex":"1) The region cannot sustain this level of tourism without damaging its resources. 2) The planet is unable to sustain human life. 3) The company has sustained heavy losses this year.","tag":"Unit 2 AV"},{"id":"en-u2-053","unit":"u2","term":"sustainable (adj)","ru":"устойчивый, экологически рациональный","def":"able to continue over time without causing lasting harm","coll":"sustainable development/practices/tourism; environmentally sustainable","ex":"The hotel claims to follow sustainable building practices.","tag":"Unit 2 AV"},{"id":"en-u2-054","unit":"u2","term":"sustainability (n)","ru":"устойчивость, устойчивое развитие","def":"the quality of being able to continue without depleting resources or causing damage","coll":"environmental sustainability; the pillars of sustainability","ex":"The three pillars of sustainability are social, environmental, and economic.","tag":"Unit 2 AV"},{"id":"en-u2-055","unit":"u2","term":"conservation (n)","ru":"охрана (природы), сохранение","def":"the protection and careful management of the environment and natural resources","coll":"wildlife/marine conservation; to promote conservation efforts; a conservation area","ex":"The reserve was created to support wildlife conservation.","tag":"Unit 2 AV"},{"id":"en-u2-056","unit":"u2","term":"to undermine (v)","ru":"подрывать","def":"to weaken or damage something gradually, often secretly","coll":"to undermine efforts/trust/economy/authority","ex":"Poor management can undermine the goals of conservation projects.","tag":"Unit 2 AV"},{"id":"en-u2-057","unit":"u2","term":"to adhere to (phr v)","ru":"придерживаться, соблюдать","def":"to follow or stick to a rule, principle, or standard","coll":"to adhere to rules/standards/principles/a policy","ex":"Not all companies adhere to the environmental standards they promote.","tag":"Unit 2 AV"},{"id":"en-u2-058","unit":"u2","term":"underlying (adj)","ru":"глубинный, лежащий в основе, скрытый","def":"important in a situation but not always easily noticed or stated clearly","coll":"underlying causes/principles/issues/motives/trends","ex":"The underlying goal of many projects is profit, not conservation.","tag":"Unit 2 AV"},{"id":"en-u2-059","unit":"u2","term":"renewable (adj)","ru":"возобновляемый","def":"able to be replaced naturally or continuously","coll":"renewable energy/resources/materials","ex":"The resort runs on renewable energy from solar panels.","tag":"Unit 2 AV"},{"id":"en-u2-060","unit":"u2","term":"to disrupt (v)","ru":"нарушать, срывать","def":"to interrupt or interfere with the normal function of sth","coll":"to disrupt an ecosystem/a community/wildlife","ex":"Construction can disrupt fragile wildlife habitats.","tag":"Unit 2 AV"},{"id":"en-u2-061","unit":"u2","term":"disruption (n)","ru":"нарушение, сбой","def":"an interruption or interference that stops sth from working normally","coll":"to cause/to contribute to/to result in disruption; environmental/major disruption","ex":"The new resort caused significant disruption to the local ecosystem.","tag":"Unit 2 AV"},{"id":"en-u2-062","unit":"u2","term":"fragile (adj)","ru":"хрупкий, уязвимый","def":"easily damaged, broken, or destroyed","coll":"a fragile ecosystem; fragile environment/economy","ex":"Coral reefs are extremely fragile and slow to recover from damage.","tag":"Unit 2 AV"},{"id":"en-u2-063","unit":"u2","term":"irreversible (adj)","ru":"необратимый","def":"impossible to change back to a previous state","coll":"irreversible damage/harm/consequences","ex":"Deforestation can cause irreversible damage to an ecosystem.","tag":"Unit 2 AV"},{"id":"en-u2-064","unit":"u2","term":"to generate (v)","ru":"производить, создавать, приносить (доход)","def":"to produce or create sth","coll":"to generate electricity/power/income/profit/benefits/jobs/ideas","ex":"Tourism can generate significant income for local communities.","tag":"Unit 2 AV"},{"id":"en-u2-065","unit":"u2","term":"to result in (phr v)","ru":"приводить к, вести к","def":"to cause something to happen as an effect","coll":"to result in damage/job losses/benefits/death","ex":"Poor regulation can result in long-term environmental harm.","tag":"Unit 2 AV"},{"id":"en-u2-066","unit":"u2","term":"adequate (adj), ant. inadequate (adj)","ru":"достаточный, надлежащий / недостаточный","def":"enough or sufficient for a particular purpose","coll":"(in)adequate resources/protection/funding/waste disposal","ex":"The area lacks adequate protection from overdevelopment.","tag":"Unit 2 AV"},{"id":"en-u2-067","unit":"u2","term":"adequately (adv), ant. inadequately (adv)","ru":"достаточно, должным образом / недостаточно","def":"in a sufficient or satisfactory way","coll":"(in)adequately regulated/funded/protected","ex":"The industry is inadequately regulated in many countries.","tag":"Unit 2 AV"},{"id":"en-u2-068","unit":"u2","term":"accountable (adj)","ru":"подотчётный, несущий ответственность","def":"responsible and required to explain one's actions","coll":"to hold sb accountable for sth; to remain accountable","ex":"Companies must be held accountable for environmental damage they cause.","tag":"Unit 2 AV"},{"id":"en-u2-069","unit":"u2","term":"accountability (n)","ru":"подотчётность, ответственность","def":"the state of being responsible for one's actions","coll":"a lack of accountability; to ensure/to demand accountability","ex":"Critics are calling for greater accountability in the ecotourism industry.","tag":"Unit 2 AV"},{"id":"en-u3-001","unit":"u3","term":"resilience (n) / resilient (adj)","ru":"жизнестойкость, способность восстанавливаться; жизнестойкий, стойкий","def":"resilience — the ability to recover quickly from difficulties, or to stay strong in hard times; resilient — able to recover quickly; tough","coll":"to show / foster / build / develop resilience; emotional / mental resilience; resilience to stress; a resilient person / economy / community; remarkably resilient","ex":"The employees showed remarkable resilience despite all the difficulties. | Children are believed to be more resilient than adults.","tag":"Unit 3 AV"},{"id":"en-u3-002","unit":"u3","term":"to bounce back (phr v)","ru":"оправиться, быстро восстановиться","def":"to recover quickly after a failure, loss or illness","coll":"to bounce back from a defeat / a crisis / an illness","ex":"He's had a lot of problems, but he always seems to bounce back pretty quickly.","tag":"Unit 3 AV"},{"id":"en-u3-003","unit":"u3","term":"inevitable (adj)","ru":"неизбежный","def":"certain to happen and impossible to avoid","coll":"an inevitable result / outcome / consequence / delay; to seem / become inevitable; it is inevitable that","ex":"A rise in interest rates is inevitable.","tag":"Unit 3 AV"},{"id":"en-u3-004","unit":"u3","term":"fragility (n)","ru":"хрупкость, ранимость; fragile — хрупкий","def":"the quality of being easily broken, damaged or upset","coll":"the fragility of peace / the economy / glass / bones; emotional / financial fragility","ex":"Her illness was a painful reminder of the fragility of life.","tag":"Unit 3 AV"},{"id":"en-u3-005","unit":"u3","term":"perspective (n)","ru":"здравый взгляд, трезвая оценка, чувство меры","def":"the ability to think about problems and decisions in a reasonable way without making them seem worse or more important than they really are","coll":"to keep sth in perspective; to put/get sth into perspective; to lose all sense of perspective; to lose perspective on sth","ex":"It's easy to lose perspective on things when you're under stress.","tag":"Unit 3 AV"},{"id":"en-u3-006","unit":"u3","term":"to overstate (v) / ant. to understate (v)","ru":"преувеличивать; understate — преуменьшать","def":"to overstate — to describe sth as more serious or important than it really is; to understate — to state that sth is smaller, less important or less serious than it really is","coll":"to overstate the risk / danger / importance / case","ex":"The seriousness of the crime cannot be overstated. | It would be a mistake to understate the seriousness of the problem.","tag":"Unit 3 AV"},{"id":"en-u3-007","unit":"u3","term":"to amplify (v)","ru":"1) усиливать; 2) распространять, увеличивать охват","def":"","coll":"to amplify sounds / voices; to amplify the effect / fears; to amplify a message / a post","ex":"This landscape seemed to trap and amplify sounds. | The posts are amplified by the platform's algorithm.","tag":"Unit 3 AV"},{"id":"en-u3-008","unit":"u3","term":"to evoke (v)","ru":"вызывать (чувство, воспоминание, образ)","def":"to bring a feeling, memory or image into the mind","coll":"to evoke memories / emotions / a response / sympathy","ex":"His case is unlikely to evoke public sympathy.","tag":"Unit 3 AV"},{"id":"en-u3-009","unit":"u3","term":"undeserved (adj)","ru":"незаслуженный (обычно о плохом)","def":"not justified by what someone has done, usually something bad or unfair","coll":"undeserved criticism / punishment / reputation / treatment","ex":"The treatment he received was harsh and undeserved.","tag":"Unit 3 AV"},{"id":"en-u3-010","unit":"u3","term":"unearned (adj)","ru":"незаработанный, нетрудовой, доставшийся без усилий","def":"obtained without having been worked for","coll":"unearned income / fortune / promotion / praise / privilege / luck","ex":"He inherited an unearned fortune and never learned the value of money.","tag":"Unit 3 AV"},{"id":"en-u3-011","unit":"u3","term":"to outweigh (v)","ru":"перевешивать","def":"to be greater in importance, value or amount than something else","coll":"the benefits outweigh the risks / costs / drawbacks; to far outweigh","ex":"The advantages of this scheme far outweigh the costs involved.","tag":"Unit 3 AV"},{"id":"en-u3-012","unit":"u3","term":"to toughen up (phr v)","ru":"закалять(ся)","def":"to make sb stronger, less easily upset, able to deal with challenges, or to become so","coll":"to toughen up a child / team; a chance to toughen up","ex":"His parents sent him away to boarding school, believing it would toughen him up.","tag":"Unit 3 AV"},{"id":"en-u3-013","unit":"u3","term":"to wallow in (phr v)","ru":"упиваться (жалостью к себе и т. п.), погрязнуть в","def":"to remain in an unhappy emotional state without trying to get out of it, as if you are enjoying it or trying to get sympathy from other people","coll":"to wallow in despair / discomfort / misery / self-pity","ex":"Why don't you do something to help yourself instead of wallowing in self-pity?","tag":"Unit 3 AV"},{"id":"en-u3-014","unit":"u3","term":"misery (n)","ru":"1) страдание, горе; 2) нищета; 3) нытик","def":"","coll":"to cause / bring misery; to make sb's life a misery; to live in misery","ex":"","tag":"Unit 3 AV"},{"id":"en-u3-015","unit":"u3","term":"to expose sb to sth (v)","ru":"знакомить, приобщать кого-л. к чему-л.","def":"to let sb find out about sth by giving them experience of it or showing them what it is like","coll":"to expose sb to art / culture / languages / new ideas","ex":"We exposed our kids to literature as much as possible.","tag":"Unit 3 AV"},{"id":"en-u3-016","unit":"u3","term":"internal (adj)","ru":"внутренний","def":"inside a person, object, organisation or country","coll":"internal organs / bleeding / affairs / investigation / conflicts; internal motivation","ex":"She struggled with her own internal conflicts.","tag":"Unit 3 AV"},{"id":"en-u3-017","unit":"u3","term":"external (adj)","ru":"внешний","def":"outside, or coming from outside a person, object, organisation or country","coll":"external factors / circumstances / pressure; an external examiner / threat","ex":"Her works show external influences.","tag":"Unit 3 AV"},{"id":"en-u3-018","unit":"u3","term":"to unleash (v)","ru":"высвободить, дать волю, раскрыть (потенциал); вызвать, развязать","def":"to suddenly let a strong force or emotion be felt or take effect","coll":"to unleash creativity / feelings / passions","ex":"The proposals unleashed a storm of protest.","tag":"Unit 3 AV"},{"id":"en-u3-019","unit":"u3","term":"novel (adj)","ru":"новый, оригинальный, новаторский","def":"different from anything known before; new, interesting and often seeming slightly strange","coll":"a novel concept / idea","ex":"Job-sharing is still a novel concept and it will take a while for employers to get used to it.","tag":"Unit 3 AV"},{"id":"en-u3-020","unit":"u3","term":"to coin (v)","ru":"придумать, ввести в обиход (слово, выражение)","def":"to invent a new word or phrase that other people then begin to use","coll":"to coin a word / phrase","ex":"Who coined the motto \"Make love, not war\"?","tag":"Unit 3 AV"},{"id":"en-u3-021","unit":"u3","term":"to embody (v) / embodiment (n)","ru":"воплощать, олицетворять; воплощение","def":"to embody — to express or represent an idea or a quality; embodiment — a person or thing that represents or is a typical example of an idea or a quality","coll":"to embody grace / justice; to be embodied in a declaration; the embodiment of evil / kindness / success","ex":"This nation embodies competitive spirit. | He is the embodiment of the English gentleman.","tag":"Unit 3 AV"},{"id":"en-u3-022","unit":"u3","term":"propensity (n)","ru":"склонность","def":"a natural desire or need that makes you tend to behave in a particular way","coll":"a propensity for violence; a propensity to do sth","ex":"He has a propensity to exaggerate.","tag":"Unit 3 AV"},{"id":"en-u3-023","unit":"u3","term":"volatility (n) / volatile (n)","ru":"нестабильность, изменчивость; нестабильный, изменчивый, взрывоопасный","def":"volatility — the quality or state of being likely to change suddenly; volatile — likely to change suddenly; easily becoming dangerous; unstable","coll":"price / market volatility; the volatility of the political situation; a potentially / highly volatile situation","ex":"The economy is set to recover, despite recent stock market volatility. | Food and fuel prices are volatile in a war situation.","tag":"Unit 3 AV"},{"id":"en-u3-024","unit":"u3","term":"to come up with (phr v)","ru":"придумать, предложить, выдвинуть","def":"to suggest sth or think of an idea, plan","coll":"to come up with a plan / scheme / theory","ex":"Who came up with this brilliant idea?","tag":"Unit 3 AV"},{"id":"en-u3-025","unit":"u3","term":"to adjust (v)","ru":"приспособиться, привыкнуть","def":"to get used to a new situation by changing the way you behave and/or think","coll":"to adjust to sth; to adjust to doing sth","ex":"It can be difficult to adjust to being a parent.","tag":"Unit 3 AV"},{"id":"en-u3-026","unit":"u3","term":"to endure (v)","ru":"терпеть, выносить","def":"to experience and deal with something that is painful or unpleasant without giving up","coll":"to endure pain / sufferings / a long wait / the thought of..","ex":"She could not endure the thought of parting.","tag":"Unit 3 AV"},{"id":"en-u3-027","unit":"u3","term":"a stepping stone (expr)","ru":"ступенька, трамплин (к чему-л.)","def":"sth that allows you to make progress or begin to achieve something","coll":"a stepping stone to success","ex":"This job is a stepping stone to better things.","tag":"Unit 3 AV"},{"id":"en-u3-028","unit":"u3","term":"to excel (v)","ru":"преуспевать, отлично справляться, выделяться","def":"to be very good at doing something","coll":"to excel in languages / at music; to excel at doing sth","ex":"The team excels at turning defence into attack.","tag":"Unit 3 AV"},{"id":"en-u3-029","unit":"u3","term":"to embrace (v)","ru":"охотно принимать; воспользоваться (возможностью)","def":"to enthusiastically accept an idea, a proposal, a set of beliefs, etc.","coll":"to embrace democracy / feminism; to embrace an opportunity","ex":"This was an opportunity he would embrace.","tag":"Unit 3 AV"},{"id":"en-u3-030","unit":"u3","term":"to cultivate (v)","ru":"развивать, культивировать; создавать (имидж, видимость)","def":"to try to develop or improve sth","coll":"to cultivate an image / air of","ex":"This modern image is cultivated by the company.","tag":"Unit 3 AV"},{"id":"en-u3-031","unit":"u3","term":"diversity (n) / diverse (adj)","ru":"разнообразие; разнообразный, разнородный","def":"diversity — a range of many people or things that are very different from each other; diverse — very different from each other and of various kinds","coll":"a rich / great diversity of ideas / opinions / views / choice; cultural / ethnic / biological diversity; diverse cultures / interests","ex":"She teaches the students to have respect for different races and appreciate the diversity of other cultures. | The school is a richly diverse community.","tag":"Unit 3 AV"},{"id":"en-u3-032","unit":"u3","term":"to facilitate (v)","ru":"облегчать, содействовать, способствовать","def":"to make an action or a process possible or easier","coll":"to facilitate access / growth / learning","ex":"The use of computers has facilitated the company's ability to keep accurate records.","tag":"Unit 3 AV"},{"id":"en-u3-033","unit":"u3","term":"continuous (adj)","ru":"непрерывный, постоянный","def":"happening or existing for a period of time without being interrupted","coll":"continuous learning / processes / improvement / flow / stream","ex":"The organization aims to foster a culture of continuous learning.","tag":"Unit 3 AV"},{"id":"en-u3-034","unit":"u3","term":"relevant (adj) / ant. irrelevant","ru":"1) относящийся к делу; 2) актуальный, востребованный, значимый; irrelevant — не относящийся к делу","def":"","coll":"(ir)relevant information / facts / documents / factors / suggestions / questions / points; (ir)relevant to discussion / life / sb's needs; vocationally relevant skills / qualifications; to stay relevant","ex":"This point is highly relevant to the discussion. | Is monarchy still relevant in the modern world?","tag":"Unit 3 AV"},{"id":"en-u3-035","unit":"u3","term":"to succumb (v)","ru":"поддаться; умереть от (болезни), сломаться от","def":"","coll":"to succumb to threats / temptation / sb's charms; to succumb to cancer / burnout","ex":"She succumbed to the temptation of another drink. | His career was cut short when he succumbed to cancer.","tag":"Unit 3 AV"},{"id":"en-u3-036","unit":"u3","term":"to harness (v)","ru":"использовать, задействовать, обуздать (силу)","def":"to control and use the force or strength of something to produce power or to achieve something","coll":"to harness creativity / skills; to harness wind / waves","ex":"We must harness the skill and creativity of our workforce.","tag":"Unit 3 AV"},{"id":"en-u3-037","unit":"u3","term":"prudent (adj) / ant. imprudent","ru":"благоразумный, осмотрительный; imprudent — неблагоразумный","def":"careful and avoiding risks","coll":"a(n) (im)prudent businessman; a(n) (im)prudent decision / investment","ex":"It's always prudent to read a contract carefully before signing it.","tag":"Unit 3 AV"},{"id":"en-u3-038","unit":"u3","term":"to backfire (v)","ru":"дать обратный эффект, обернуться против (кого-л.), выйти боком","def":"to have the opposite effect to the one intended, with bad or dangerous results","coll":"to backfire disastrously; to backfire on sb","ex":"The surprise I had planned backfired on me.","tag":"Unit 3 AV"},{"id":"en-u3-039","unit":"u3","term":"to attain (v) / (un)attainable (adj)","ru":"достигать, добиваться; (не)достижимый","def":"to attain — to succeed in getting something, usually after a lot of effort; (un)attainable — that you can(not) achieve","coll":"to attain a goal / degree / standard / level; to attain proficiency / mastery / independence well-being (так в материале, без разделителя; *вероятно, «independence / well-being»); (un)attainable goals / objectives / targets","ex":"You need financial security to attain emotional well-being. | This standard is easily attainable by most students.","tag":"Unit 3 AV"},{"id":"en-u3-040","unit":"u3","term":"to pursue (v) / pursuit (n)","ru":"преследовать (цель), стремиться к; pursuit — 1) стремление, погоня за; 2) занятие, увлечение","def":"to pursue — to do something or try to achieve something over a period of time; pursuit — 1) the act of looking for or trying to get something; 2) something that you give your time and energy to and that you do as a hobby","coll":"to pursue a policy / a career / a dream / a strategy; the pursuit of happiness / success / knowledge / profit; outdoor / leisure / artistic pursuits","ex":"What marketing strategy should we pursue for this new product? | She is engaged in pursuit of pleasure. | She has no time to follow her various artistic pursuits.","tag":"Unit 3 AV"},{"id":"en-u3-041","unit":"u3","term":"vulnerable (adj) / vulnerability (n)","ru":"уязвимый, ранимый, подверженный; уязвимость, подверженность","def":"vulnerable — easily hurt, harmed or attacked, physically or emotionally; vulnerability — the fact of being weak and easily hurt physically or emotionally","coll":"vulnerable to stress / infection / attack / criticism; vulnerable groups / children / members; to feel / become vulnerable; economically / emotionally vulnerable; vulnerability to stress / attack / infection; to expose / reveal / highlight vulnerabilities; to show vulnerability; emotional / financial / security vulnerability","ex":"Employees who fear for their jobs are especially vulnerable to stress. | A leader who admits vulnerability often earns more trust.","tag":"Unit 3 AV"},{"id":"en-u3-042","unit":"u3","term":"compassion (n) / compassionate (adj)","ru":"сострадание; сострадательный, отзывчивый","def":"compassion — a feeling of sympathy for someone's suffering, together with a wish to help; compassionate — feeling or showing sympathy and concern for others' suffering","coll":"deep / genuine / great compassion; to show / feel / have / express compassion for / towards sb; to treat sb with compassion; compassion fatigue; a compassionate manager / person; compassionate leave","ex":"The manager showed great compassion when a colleague lost a relative. | A compassionate employer offers real support during hard times.","tag":"Unit 3 AV"},{"id":"en-u3-043","unit":"u3","term":"to nurture (v)","ru":"растить, взращивать, пестовать, лелеять","def":"to care for and encourage the growth or development of someone or something","coll":"to nurture talent / a child / a relationship / a dream / an idea / trust / creativity; carefully / lovingly nurtured","ex":"Prudent leaders nurture trust within their teams.","tag":"Unit 3 AV"},{"id":"en-u3-044","unit":"u3","term":"to deplete (v)","ru":"истощать, исчерпывать","def":"to reduce sth greatly in quantity, so that little is left (energy, money, resources)","coll":"to deplete resources / reserves / supplies / stocks / funds / savings; seriously / severely / rapidly depleted","ex":"Constant overwork can deplete a person's energy and motivation.","tag":"Unit 3 AV"},{"id":"en-u3-045","unit":"u3","term":"to chase (v)","ru":"гнаться за, добиваться","def":"to try to obtain or achieve something, for example money, work or success","coll":"to chase success / a dream / profit / fame / money / deadlines / a promotion / a target","ex":"After years of chasing her dream, she finally got a part in a movie.","tag":"Unit 3 AV"},{"id":"en-u3-046","unit":"u3","term":"life-affirming (adj)","ru":"жизнеутверждающий","def":"giving a sense of hope, joy or the value of life; positive and uplifting","coll":"a life-affirming experience / story / message / event / moment; deeply / truly life-affirming","ex":"Volunteering was a life-affirming experience for her.","tag":"Unit 3 AV"},{"id":"en-u3-047","unit":"u3","term":"to strive (v) (strove, striven)","ru":"стремиться, прилагать усилия","def":"to make great efforts to achieve something; to try very hard","coll":"to strive for perfection / excellence / success / equality / balance / improvement","ex":"","tag":"Unit 3 AV"},{"id":"en-u3-048","unit":"u3","term":"fulfilling (adj) / fulfillment (n)","ru":"приносящий удовлетворение; удовлетворение, самореализация","def":"fulfilling — giving a feeling of satisfaction and achievement because you are using your abilities or reaching your goals; fulfillment — the feeling of satisfaction that comes from achieving something or developing one's potential","coll":"a fulfilling career / job / life / relationship / experience; to find sth fulfilling; to find / seek / achieve / gain personal / emotional / spiritual fulfilment; a sense of fulfilment; self-fulfilment","ex":"She found teaching deeply fulfilling. | Many people seek fulfillment in meaningful work.","tag":"Unit 3 AV"},{"id":"en-u3-049","unit":"u3","term":"to resonate with (phr v)","ru":"находить отклик у, быть созвучным","def":"to feel meaningful or familiar to sb because it matches their experience or feelings","coll":"to resonate with readers / listeners / customers; the message / story / idea / song / speech resonates with","ex":"The speaker's story about burnout resonated with many people in the audience","tag":"Unit 3 AV"},{"id":"en-u3-050","unit":"u3","term":"relentless (adj)","ru":"неослабевающий, неустанный, неутомимый; безжалостный","def":"continuing without stopping or weakening; harsh, severe or unyielding","coll":"relentless pressure / pursuit / criticism / competition / optimism / determination; relentless in one's pursuit of","ex":"The relentless pressure to meet targets left the team exhausted. | The student was relentless in his pursuit of the knowledge.","tag":"Unit 3 AV"}],"collocations":[{"id":"en-c01","unit":"u1","prompt":"to ___ innovation / cooperation / resilience","answer":"foster","options":["foster","address","adapt","refer"],"full":"to foster innovation / cooperation","ru":"способствовать развитию, укреплять","rule":"Unit 1 AV: to foster innovation, creativity, cooperation, understanding."},{"id":"en-c02","unit":"u1","prompt":"to ___ an issue / a concern / the needs of students","answer":"address","options":["address","enhance","tailor","engage"],"full":"to address an issue / concern","ru":"заниматься проблемой, решать вопрос","rule":"Unit 1 AV: to address an issue / problem / concern / needs."},{"id":"en-c03","unit":"u1","prompt":"to have a huge impact ___ young people","answer":"on","options":["on","to","for","at"],"full":"to have an impact on sb/sth","ru":"оказывать сильное влияние на","rule":"impact (n) + ON; to impact (v) sth / on sth."},{"id":"en-c04","unit":"u1","prompt":"to adapt ___ a changing environment","answer":"to","options":["to","for","with","at"],"full":"to adapt to a new environment","ru":"приспосабливаться к новой среде","rule":"adapt TO sth; adapt a novel FOR screen."},{"id":"en-c05","unit":"u1","prompt":"to ___ the quality of life / career prospects","answer":"enhance","options":["enhance","identify","adapt","refer"],"full":"to enhance the quality of life","ru":"повышать качество жизни / карьерные перспективы","rule":"Unit 1 AV: enhance quality of life / reputation / productivity / performance."},{"id":"en-c06","unit":"u2","prompt":"to embark ___ a new career / adventure","answer":"on","options":["on","in","to","at"],"full":"to embark on a career / project","ru":"приступать к новой карьере / проекту","rule":"Unit 2 AV: to embark ON sth new and important."},{"id":"en-c07","unit":"u2","prompt":"to delve ___ history / sb's private life","answer":"into","options":["into","on","at","through"],"full":"to delve into history / the past","ru":"углубляться, вникать в","rule":"Unit 2 AV: to delve INTO sth."},{"id":"en-c08","unit":"u2","prompt":"to immerse oneself ___ a language and culture","answer":"in","options":["in","into","to","at"],"full":"to immerse oneself in sth","ru":"полностью погрузиться во что-л.","rule":"Unit 2 AV: to immerse oneself IN sth; to be immersed IN sth."},{"id":"en-c09","unit":"u2","prompt":"to feel compelled ___ do sth","answer":"to","options":["to","of","for","in"],"full":"to feel compelled to do sth","ru":"чувствовать себя вынужденным сделать что-л.","rule":"Unit 2 AV: compel sb TO do sth; feel compelled TO do sth."},{"id":"en-c10","unit":"u2","prompt":"to ___ sales / morale / self-esteem","answer":"boost","options":["boost","absorb","compel","delve"],"full":"to boost morale / self-esteem","ru":"повышать боевой дух / самооценку","rule":"Unit 2 AV: boost sales, exports, economy, morale, confidence, self-esteem."},{"id":"en-c11","unit":"u3","prompt":"to bounce ___ from a defeat / crisis","answer":"back","options":["back","up","out","over"],"full":"to bounce back from a defeat","ru":"быстро оправиться после неудачи / кризиса","rule":"Unit 3 AV: to bounce back from a defeat / crisis / illness."},{"id":"en-c12","unit":"u3","prompt":"to accuse / suspect sb ___ doing sth","answer":"of","options":["of","for","on","from"],"full":"accuse / suspect sb of + Gerund","ru":"обвинять / подозревать кого-л. в чём-л.","rule":"Unit 3 Grammar File: accuse sb OF, suspect sb OF, complain OF, approve OF, hear OF, think OF + Gerund."},{"id":"en-c13","unit":"u3","prompt":"to prevent / stop sb ___ entering","answer":"from","options":["from","of","to","out"],"full":"prevent / stop sb from + Gerund","ru":"помешать кому-л. войти","rule":"Unit 3 Grammar File: prevent sb FROM, stop sb FROM + Gerund."},{"id":"en-c14","unit":"u3","prompt":"to insist ___ doing additional tests","answer":"on","options":["on","in","for","of"],"full":"insist on + Gerund","ru":"настаивать на проведении тестов","rule":"Unit 3 Grammar File: insist ON, depend ON, congratulate sb ON + Gerund."},{"id":"en-c15","unit":"u3","prompt":"to succeed ___ changing one's lifestyle","answer":"in","options":["in","on","at","with"],"full":"succeed in + Gerund","ru":"преуспеть в изменении образа жизни","rule":"Unit 3 Grammar File: succeed IN, result IN, engage IN + Gerund."},{"id":"en-c16","unit":"u3","prompt":"to object ___ visiting in large groups","answer":"to","options":["to","against","of","for"],"full":"object to + Gerund","ru":"возражать против посещения в больших группах","rule":"В object TO и look forward TO слово to — предлог → нужен герундий (-ing)!"},{"id":"en-c17","unit":"u3","prompt":"to blame / thank / apologize ___ missing the deadline","answer":"for","options":["for","of","about","on"],"full":"blame / thank / apologize for + Gerund","ru":"винить / благодарить / извиняться за","rule":"Unit 3 Grammar File: blame sb FOR, thank sb FOR, apologize FOR + Gerund."},{"id":"en-c18","unit":"u3","prompt":"There is no point ___ complaining.","answer":"in","options":["in","of","to","for"],"full":"There's no point in + Gerund","ru":"Нет смысла жаловаться.","rule":"Unit 3 Grammar File: There's no point IN + Gerund; It's no use / no good + Gerund (без предлога)."}],"tricky":[{"id":"en-t01","unit":"u3","pair":"remember doing vs remember to do","prompt":"«Я помню, как закрывал дверь» vs «Не забудь закрыть дверь»:","options":["remember locking / remember to lock","remember to lock / remember locking","В обоих случаях to lock"],"answer":"remember locking / remember to lock","explain":"remember + Gerund = помнить прошлое событие; remember + to-Infinitive = не забыть сделать (задача на будущее)."},{"id":"en-t02","unit":"u3","pair":"stop doing vs stop to do","prompt":"«Он остановился, чтобы передохнуть» — какой вариант верен?","options":["He stopped to rest.","He stopped resting.","Оба верны и значат одно и то же."],"answer":"He stopped to rest.","explain":"stop + Gerund = прекратить делать; stop + to-Infinitive = остановиться с целью сделать что-то другое."},{"id":"en-t03","unit":"u3","pair":"try doing vs try to do","prompt":"«Попробуй добавить немного соли (как эксперимент)»:","options":["Try adding a little salt.","Try to add a little salt.","Try add a little salt."],"answer":"Try adding a little salt.","explain":"try + Gerund = попробовать в качестве эксперимента/способа; try + to-Infinitive = стараться, прилагать усилия."},{"id":"en-t04","unit":"u3","pair":"regret doing vs regret to say","prompt":"«С сожалением сообщаем, что рейс отменён»:","options":["We regret to inform you...","We regret informing you...","We regret inform you..."],"answer":"We regret to inform you...","explain":"regret + to-Infinitive (say/tell/inform) = сообщать плохую новость; regret + Gerund = сожалеть о совершённом в прошлом."},{"id":"en-t05","unit":"u3","pair":"Active vs Passive Gerund","prompt":"«Она не выносит, когда её перебивают»:","options":["She can't stand being interrupted.","She can't stand interrupting.","She can't stand to be interrupt."],"answer":"She can't stand being interrupted.","explain":"Действие направлено на подлежащее (перебивают ЕЁ) → Simple Passive Gerund: being + V3."},{"id":"en-t06","unit":"u3","pair":"suggest + Gerund (ловушка!)","prompt":"Как правильно: «Они предложили нам посетить выставку»?","options":["They suggested visiting the exhibition.","They suggested us to visit the exhibition.","They suggested to us visiting."],"answer":"They suggested visiting the exhibition.","explain":"После suggest НЕЛЬЗЯ ставить sb + to-Infinitive! Только suggest + Gerund (или suggest that we should visit)."},{"id":"en-t07","unit":"u1","pair":"Complex Subject: Simple vs Perfect Infinitive","prompt":"«Известно, что он написал эту книгу в прошлом году»:","options":["He is known to have written this book last year.","He is known to write this book last year.","He is known writing this book last year."],"answer":"He is known to have written this book last year.","explain":"Если действие в Complex Subject произошло РАНЬШЕ (в прошлом) → Perfect Infinitive (to have + V3)."},{"id":"en-t08","unit":"u1","pair":"be likely vs be bound vs happen","prompt":"Что выражает «He happened to know the answer»?","options":["Случайно оказалось, что он знал ответ","Он наверняка знал ответ","Вряд ли он знал ответ"],"answer":"Случайно оказалось, что он знал ответ","explain":"happen / chance + Inf = случайно оказаться; be likely = вероятно; be bound = непременно, наверняка."},{"id":"en-t09","unit":"u2","pair":"Participle I vs Participle II","prompt":"«Ошеломлённый новостью, он не мог сказать ни слова»:","options":["Shocked by the news, he couldn't say a word.","Shocking by the news, he couldn't say a word.","Having shocking by the news..."],"answer":"Shocked by the news, he couldn't say a word.","explain":"Participle II (V3) — пассивное значение (он испытал шок); Participle I (-ing) — активное (производящий эффект)."},{"id":"en-t10","unit":"u2","pair":"Русские причастия на -вший (ловушка!)","prompt":"Как перевести «туристы, посетившие этот город в прошлом году»?","options":["the tourists who visited this city last year","the tourists having visited this city last year","the tourists visiting this city last year"],"answer":"the tourists who visited this city last year","explain":"Unit 2 Grammar File: Perfect Participle (having done) НЕ используется в функции определения! Для русских причастий на -вший используем придаточное (who visited)."}],"exercises":[{"id":"en-g1-01","unit":"u1","source":"Grammar File Unit 1 · Infinitive Forms","section":"Complex Subject · Passive Reporting","type":"choice","prompt":"AI is believed ___ education dramatically over the next decade.","answer":"to transform","options":["to transform","to have transformed","transforming","to be transformed"],"ru":"Считается, что ИИ кардинально изменит образование в ближайшем десятилетии.","explain":"Речь о будущем/настоящем, активный залог → Simple Active Infinitive (to transform)."},{"id":"en-g1-02","unit":"u1","source":"Grammar File Unit 1 · Complex Subject","section":"Complex Subject · Past Action","type":"choice","prompt":"The student is reported ___ the scholarship last week.","answer":"to have won","options":["to have won","to win","winning","to be winning"],"ru":"Сообщают, что студент выиграл стипендию на прошлой неделе.","explain":"Действие предшествует глаголу сообщения (last week) → Perfect Infinitive (to have + V3)."},{"id":"en-g1-03","unit":"u1","source":"Grammar File Unit 1 · Complex Subject","section":"Complex Subject · Seem / Appear","type":"choice","prompt":"She seems ___ hard on her project right now.","answer":"to be working","options":["to be working","to work","to have worked","working"],"ru":"Кажется, она сейчас усердно работает над своим проектом.","explain":"Действие в процессе прямо сейчас (right now) → Continuous Infinitive (to be + V-ing)."},{"id":"en-g1-04","unit":"u1","source":"Grammar File Unit 1 · Complex Subject","section":"Complex Subject · Turn out / Prove","type":"choice","prompt":"The new curriculum turned out ___ very effective.","answer":"to be","options":["to be","being","be","to have been being"],"ru":"Новая учебная программа оказалась очень эффективной.","explain":"turn out / prove + to-Infinitive."},{"id":"en-g1-05","unit":"u1","source":"Grammar File Unit 1 · Complex Subject","section":"Be likely / unlikely / bound","type":"choice","prompt":"They are ___ to succeed if they keep fostering innovation.","answer":"bound","options":["bound","happened","seemed","believed"],"ru":"Они непременно добьются успеха, если продолжат развивать инновации.","explain":"be bound to do sth = непременно, наверняка; be likely to = вероятно."},{"id":"en-g2-01","unit":"u2","source":"Grammar File Unit 2 · Participles","section":"Participle as Adverbial Modifier","type":"choice","prompt":"___ all the preparations, they embarked on the expedition.","answer":"Having finished","options":["Having finished","Finishing","Finished","Being finished"],"ru":"Завершив все приготовления, они отправились в экспедицию.","explain":"Предшествующее активное действие → Perfect Participle Active (Having + V3)."},{"id":"en-g2-02","unit":"u2","source":"Grammar File Unit 2 · Participles","section":"Being vs When","type":"choice","prompt":"___ a tourist in Venice, you should respect local residents.","answer":"When","options":["When","Being","Having been","Been"],"ru":"Будучи туристом (когда вы турист) в Венеции, стоит уважать местных жителей.","explain":"Being = причина («поскольку я турист»); When = время/условие («когда ты турист»)."},{"id":"en-g2-03","unit":"u2","source":"Grammar File Unit 2 · Participles","section":"Not vs Without","type":"choice","prompt":"___ knowing the local language, he struggled to communicate.","answer":"Not","options":["Not","Without","No","Don't"],"ru":"Не зная местного языка, он с трудом общался.","explain":"Причина → Not + V-ing (Not knowing). Сопутствующее обстоятельство («не сделав чего-л.») → Without + V-ing (He left without saying goodbye)."},{"id":"en-g2-04","unit":"u2","source":"Grammar File Unit 2 · Participles","section":"Verbs of Motion / Perception","type":"choice","prompt":"___ the city centre, the travellers noticed how overcrowded it was.","answer":"Entering","options":["Entering","Having entered","Entered","Being entered"],"ru":"Войдя в центр города, путешественники заметили, насколько он переполнен.","explain":"Unit 2 Grammar File: с глаголами движения/восприятия (enter, arrive, hear, see) для непосредственно предшествующего действия используется Simple Participle I (Entering), а не Having entered."},{"id":"en-g3-001","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The hospital postponed ___ the new appointment system because of technical problems.","answer":"introducing","ru":"Больница отложила внедрение новой системы записи на приём из-за технических проблем.","explain":"postpone + Ger, без предлога"},{"id":"en-g3-002","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"Would you mind ___ the window? It is rather cold in here.","answer":"closing","ru":"Вы не могли бы закрыть окно? Здесь довольно холодно.","explain":"mind + Ger, без предлога"},{"id":"en-g3-003","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The professor thanked the students ___ in the international conference.","answer":"for participating","ru":"Профессор поблагодарил студентов за участие в международной конференции.","explain":"thank sb for + Ger"},{"id":"en-g3-004","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The company was blamed ___ clear instructions to its customers.","answer":"for not providing","ru":"Компанию обвинили в том, что она не предоставила клиентам чётких инструкций.","explain":"blame sb for; not ставится перед герундием"},{"id":"en-g3-005","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"Some people cannot imagine ___ in a city without public transport.","answer":"living","ru":"Некоторые люди не представляют себе жизни в городе без общественного транспорта.","explain":"imagine + Ger, без предлога"},{"id":"en-g3-006","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The patient complained ___ unable to sleep after taking the new medicine.","answer":"of being","ru":"Пациент жаловался на то, что не может спать после приёма нового лекарства.","explain":"complain of — по списку файла; в речи также about"},{"id":"en-g3-007","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The police suspected the driver ___ the parked car.","answer":"of damaging","ru":"Полиция подозревала водителя в том, что он повредил припаркованную машину.","explain":"suspect sb of; допустимо of having damaged"},{"id":"en-g3-008","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The charity is thinking ___ a campaign to support homeless animals.","answer":"of launching","ru":"Благотворительная организация подумывает о запуске кампании в поддержку бездомных животных.","explain":"think of + Ger"},{"id":"en-g3-009","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"The children were prevented ___ the laboratory without adult supervision.","answer":"from entering","ru":"Детей не пустили в лабораторию без присмотра взрослых.","explain":"prevent sb from + Ger"},{"id":"en-g3-010","unit":"u3","source":"Grammar File Unit 3 · Упр. 7","section":"Упр. 7 — Complete the sentences (Gerund + preposition where required)","type":"input","prompt":"I really appreciate ___ the opportunity to speak at this event.","answer":"being given","ru":"Я очень признателен за то, что мне дали возможность выступить на этом мероприятии.","explain":"без предлога; Passive Gerund — возможность дали мне"},{"id":"en-g3-011","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The doctor suggested ___ direct sunlight during the treatment.","answer":"avoiding","ru":"Врач посоветовал избегать прямых солнечных лучей во время лечения.","explain":"suggest + Ger"},{"id":"en-g3-012","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The tourists decided ___ the old town on foot.","answer":"to explore","ru":"Туристы решили осмотреть старый город пешком.","explain":"decide + to-inf"},{"id":"en-g3-013","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"My brother wants ___ a professional photographer.","answer":"to become","ru":"Мой брат хочет стать профессиональным фотографом.","explain":"want + to-inf"},{"id":"en-g3-014","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The guide suggested ___ the castle before noon.","answer":"visiting","ru":"Гид предложил посетить замок до полудня.","explain":"suggest + Ger"},{"id":"en-g3-015","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The patient refused ___ the personal questions.","answer":"to answer","ru":"Пациент отказался отвечать на личные вопросы.","explain":"refuse + to-inf"},{"id":"en-g3-016","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The scientist admitted ___ an error in the calculations.","answer":"making","ru":"Учёный признал, что допустил ошибку в расчётах.","explain":"admit + Ger"},{"id":"en-g3-017","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"We hope ___ a solution to the problem soon.","answer":"to find","ru":"Мы надеемся вскоре найти решение проблемы.","explain":"hope + to-inf"},{"id":"en-g3-018","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The children enjoyed ___ the dolphins at the aquarium.","answer":"watching","ru":"Дети с удовольствием наблюдали за дельфинами в океанариуме.","explain":"enjoy + Ger"},{"id":"en-g3-019","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"She promised ___ the documents by Friday.","answer":"to send","ru":"Она пообещала прислать документы к пятнице.","explain":"promise + to-inf"},{"id":"en-g3-020","unit":"u3","source":"Grammar File Unit 3 · Упр. 10","section":"Упр. 10 — Gerund or Infinitive","type":"input","prompt":"The company postponed ___ its new website.","answer":"launching","ru":"Компания отложила запуск своего нового сайта.","explain":"postpone + Ger"},{"id":"en-g3-021","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The photographer plans ___ part in an international competition.","answer":"to take","ru":"Фотограф планирует принять участие в международном конкурсе.","explain":"plan + to-inf"},{"id":"en-g3-022","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The doctor insisted on ___ more water during the hot weather.","answer":"drinking","ru":"Врач настаивал на том, чтобы в жару пить больше воды.","explain":"после предлога on → Ger"},{"id":"en-g3-023","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The students refused ___ in the experiment without further explanation.","answer":"to participate","ru":"Студенты отказались участвовать в эксперименте без дополнительных объяснений.","explain":"refuse + to-inf"},{"id":"en-g3-024","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The local council is considering ___ a new sports centre.","answer":"building","ru":"Местные власти рассматривают возможность строительства нового спортивного центра.","explain":"consider + Ger"},{"id":"en-g3-025","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"My parents expect me ___ home before midnight.","answer":"to return","ru":"Родители ждут, что я вернусь домой до полуночи.","explain":"expect sb + to-inf"},{"id":"en-g3-026","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The journalist denied ___ money for publishing the article.","answer":"receiving","ru":"Журналист отрицал, что получил деньги за публикацию статьи.","explain":"deny + Ger"},{"id":"en-g3-027","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The museum decided ___ free admission for schoolchildren.","answer":"to introduce","ru":"Музей решил ввести бесплатный вход для школьников.","explain":"decide + to-inf"},{"id":"en-g3-028","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The athlete risked ___ himself by continuing the competition.","answer":"injuring","ru":"Продолжая соревнование, спортсмен рисковал получить травму.","explain":"risk + Ger"},{"id":"en-g3-029","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"We agreed ___ outside the railway station.","answer":"to meet","ru":"Мы договорились встретиться у железнодорожного вокзала.","explain":"agree + to-inf"},{"id":"en-g3-030","unit":"u3","source":"Grammar File Unit 3 · Упр. 11","section":"Упр. 11 — Gerund or Infinitive","type":"input","prompt":"The teacher suggested ___ a debate on environmental issues.","answer":"organising","ru":"Учитель предложил организовать дебаты по экологическим проблемам.","explain":"suggest + Ger"},{"id":"en-g3-031","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Столкнувшись с трудной ситуацией, жизнестойкие люди часто стараются сосредоточиться на том, что они могут контролировать. _(___ — при / сразу после)_","answer":"on facing","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-032","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Она улучшила своё психическое благополучие, проводя меньше времени в соцсетях. _(___ — посредством, за счёт того что)_","answer":"by spending","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-033","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Несмотря на то что его окружала неопределённость, ему удалось сохранить оптимизм. _(___ — Passive Gerund)_","answer":"despite being surrounded","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-034","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Программа даёт участникам возможность лучше осознавать свои эмоции. _(___ ; дословно: развить большую эмоциональную осознанность)_","answer":"opportunity of developing","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-035","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Нет смысла сравнивать свою жизнь с тщательно отредактированными картинками в соцсетях. _(___ )_","answer":"there is no point in comparing","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-036","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"У неё есть привычка каждый вечер записывать три вещи, за которые она благодарна. _(___ )_","answer":"habit of writing down","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-037","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Без поддержки окружающих справляться с длительным стрессом может быть гораздо труднее. _(___ — Passive Gerund)_","answer":"without being supported","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-038","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Намерение стать более жизнестойким побудило его изменить свой распорядок дня. _(___ )_","answer":"intention of becoming","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-039","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Не стоит жертвовать своим счастьем ради одобрения других людей. _(___ )_","answer":"it's not worth sacrificing","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-040","unit":"u3","source":"Grammar File Unit 3 · Упр. 13","section":"Упр. 13 — Translate into Russian","type":"input","prompt":"Опасаясь осуждения, некоторые люди избегают открыто говорить о своих эмоциональных проблемах. _(___ — из страха, что осудят)_","answer":"for fear of being judged","ru":"","explain":"Упр. 13 — Translate into Russian"},{"id":"en-g3-041","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"Many people feel more energetic after ___ some time outdoors.","answer":"spending","ru":"Многие люди чувствуют себя бодрее, проведя какое-то время на свежем воздухе.","explain":"after + Ger"},{"id":"en-g3-042","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"She became more confident by ___ small challenges every day.","answer":"facing","ru":"Она стала увереннее в себе благодаря тому, что каждый день справлялась с небольшими трудностями.","explain":"by + Ger = благодаря тому что"},{"id":"en-g3-043","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The participants were encouraged to practise mindfulness without ___ guilty about taking time for themselves.","answer":"feeling","ru":"Участникам советовали практиковать осознанность, не испытывая чувства вины за то, что они уделяют время себе.","explain":"without + Ger"},{"id":"en-g3-044","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"Despite ___ several setbacks, the athlete continued working towards her goal.","answer":"experiencing","ru":"Несмотря на ряд неудач, спортсменка продолжала двигаться к своей цели.","explain":"despite + Simple Gerund"},{"id":"en-g3-045","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"He is used to ___ with unexpected changes in his life.","answer":"dealing","ru":"Он привык справляться с неожиданными переменами в жизни.","explain":"be used to: to — предлог → Ger"},{"id":"en-g3-046","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The patient has trouble ___ a realistic daily routine.","answer":"creating","ru":"Пациенту трудно составить реалистичный распорядок дня.","explain":"have trouble + Ger"},{"id":"en-g3-047","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The young woman had difficulty ___ that she could not control every situation.","answer":"accepting","ru":"Молодой женщине было трудно смириться с тем, что она не может контролировать каждую ситуацию.","explain":"have difficulty + Ger"},{"id":"en-g3-048","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The community showed its resilience by ___ people affected by the crisis.","answer":"supporting","ru":"Сообщество проявило стойкость, поддержав людей, пострадавших от кризиса.","explain":"by + Ger"},{"id":"en-g3-049","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The new approach involves ___ people more freedom to choose how they manage stress.","answer":"giving","ru":"Новый подход предполагает, что людям дают больше свободы в выборе способов справляться со стрессом.","explain":"involve + Ger"},{"id":"en-g3-050","unit":"u3","source":"Grammar File Unit 3 · Упр. 14","section":"Упр. 14 — Complete with the Gerund","type":"input","prompt":"The child gradually became accustomed to ___ less time online before going to bed.","answer":"spending","ru":"Ребёнок постепенно привык проводить меньше времени в интернете перед сном.","explain":"be accustomed to + Ger"},{"id":"en-g3-051","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"There is no point ___ about things that are outside your control.","answer":"in worrying","ru":"Нет смысла беспокоиться о том, что от тебя не зависит.","explain":"Упр. 15 — Complete with the Gerund (+ preposition where required)"},{"id":"en-g3-052","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"The organisation is in favour ___ flexible working hours to improve employees' well-being.","answer":"of introducing","ru":"Организация выступает за введение гибкого графика работы, чтобы улучшить самочувствие сотрудников.","explain":"Упр. 15 — Complete with the Gerund (+ preposition where required)"},{"id":"en-g3-053","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"She can't help ___ whenever she thinks about her childhood holidays.","answer":"smiling","ru":"Она не может сдержать улыбку, когда вспоминает свои детские каникулы.","explain":"без предлога"},{"id":"en-g3-054","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"The researchers found a way ___ people's sense of happiness.","answer":"of measuring","ru":"Исследователи нашли способ измерить, насколько люди ощущают себя счастливыми.","explain":"way of — по списку файла; также way to measure"},{"id":"en-g3-055","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"He has trouble ___ his emotions when he feels under pressure.","answer":"expressing","ru":"Ему трудно выражать свои эмоции, когда он чувствует давление.","explain":"без предлога"},{"id":"en-g3-056","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"The coach is busy ___ the team for a demanding competition.","answer":"preparing","ru":"Тренер занят подготовкой команды к трудным соревнованиям.","explain":"без предлога"},{"id":"en-g3-057","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"What is the use ___ yourself for something you cannot change?","answer":"of blaming","ru":"Какой смысл винить себя в том, что ты не можешь изменить?","explain":"Упр. 15 — Complete with the Gerund (+ preposition where required)"},{"id":"en-g3-058","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"The psychologist was good ___ people identify their emotional triggers.","answer":"at helping","ru":"Психолог умел помогать людям распознавать, что вызывает у них сильные эмоциональные реакции.","explain":"Упр. 15 — Complete with the Gerund (+ preposition where required)"},{"id":"en-g3-059","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"They had a hard time ___ to life in a completely new environment.","answer":"adjusting","ru":"Им было очень трудно приспособиться к жизни в совершенно новой обстановке.","explain":"без предлога; adjust to — AV"},{"id":"en-g3-060","unit":"u3","source":"Grammar File Unit 3 · Упр. 15","section":"Упр. 15 — Complete with the Gerund (+ preposition where required)","type":"input","prompt":"It's no good ___ that everything is fine when you are clearly exhausted.","answer":"pretending","ru":"Бесполезно делать вид, что всё в порядке, когда ты явно вымотан.","explain":"без предлога"}],"cheatsheets":[{"unit":"u1","title":"Unit 1 · Infinitive Forms & Complex Subject","blocks":[{"heading":"4 формы инфинитива","body":"• Simple Active: to do (одновременно / вообще)\n• Continuous Active: to be doing (в процессе сейчас)\n• Perfect Active: to have done (произошло раньше)\n• Simple Passive: to be done · Perfect Passive: to have been done"},{"heading":"Complex Subject (5 групп)","body":"1) Passive reporting: is said / known / believed / reported / expected + to-Inf\n2) Seem / appear + to-Inf (кажется, по-видимому)\n3) Turn out / prove + to-Inf (оказаться)\n4) Happen / chance + to-Inf (случайно оказаться)\n5) Be likely / unlikely / sure / certain / bound + to-Inf"}]},{"unit":"u2","title":"Unit 2 · Participles & Participle Clauses","blocks":[{"heading":"Формы причастия","body":"• Participle I Simple: doing (актив) / being done (пассив)\n• Participle I Perfect: having done (раньше, актив) / having been done (раньше, пассив)\n• Participle II: done (пассивное определение/обстоятельство)"},{"heading":"Главные ловушки Unit 2","body":"• Русские причастия на -вший (определение) переводятся через придаточное who/which + Past Simple, а НЕ having done!\n• С глаголами движения и восприятия (arriving, seeing, hearing) — Simple Participle I, а не Perfect.\n• Not + V-ing = причина; Without + V-ing = «не сделав чего-л.»."}]},{"unit":"u3","title":"Unit 3 · Gerund (Герундий)","blocks":[{"heading":"4 формы + отрицание","body":"• Simple Active: doing · Simple Passive: being done\n• Perfect Active: having done · Perfect Passive: having been done\n• Отрицание: NOT перед герундием (not getting enough sleep)."},{"heading":"Глаголы + Gerund без предлога","body":"admit, appreciate, avoid, consider, delay, deny, detest, dislike, enjoy, escape, excuse, fancy, finish, forgive, imagine, include, involve, justify, mention, mind, miss, postpone, practice, recall, resent, risk, suggest.\nФразовые: burst out, give up, keep on, leave off, look forward to, put off."},{"heading":"Глаголы с предлогом + Gerund","body":"• OF: accuse sb of, approve of, complain of, hear of, suspect sb of, think of\n• FOR: apologize for, blame sb for, thank sb for\n• ON: congratulate sb on, depend on, insist on\n• IN: engage in, result in, succeed in\n• FROM: prevent sb from, stop sb from · TO: object to, look forward to"},{"heading":"Устойчивые выражения + Gerund","body":"It's no use / no good · It's (not) worth · There's no point in · feel like · can't stand / can't bear · can't help · have difficulty (in) · spend/waste time."}]}]};
